-- Read-only holdout scoring with coefficients fit only on 2015-2017.
WITH scored AS (SELECT a.dateTime,a.outTemp AS y,r.temperature_c AS ref,(0.7886750170162296+0.9352562666974354*r.temperature_c+-0.2012939974120906*SIN(2*PI()*MOD(a.dateTime,86400)/86400)+-0.09305546547425936*COS(2*PI()*MOD(a.dateTime,86400)/86400)+-0.3075224035244028*SIN(2*PI()*(CASE WHEN a.dateTime<1577836800 THEN a.dateTime-1546300800 ELSE a.dateTime-1577836800 END)/(CASE WHEN a.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))+-1.496803043901965*COS(2*PI()*(CASE WHEN a.dateTime<1577836800 THEN a.dateTime-1546300800 ELSE a.dateTime-1577836800 END)/(CASE WHEN a.dateTime>=1577836800 THEN 31622400 ELSE 31536000 END))) AS model,CASE WHEN a.outTemp<=0 THEN 'freeze' ELSE 'above_freezing' END AS regime,CASE WHEN r.temperature_c=0 AND a.outTemp>=20 THEN 1 ELSE 0 END AS suspect_zero_hot,CASE WHEN a.dateTime<1577836800 THEN 2019 ELSE 2020 END AS yr FROM loucka_reconstruction.archive a JOIN loucka_reconstruction.reference_observations r ON r.station_id='luhamet_sehradice' AND r.observed_at_utc=a.dateTime WHERE a.dateTime>=1546300800 AND a.dateTime<1609459200 AND a.outTemp IS NOT NULL AND r.temperature_c IS NOT NULL AND r.source_resolution='5min' AND r.quality_status='reference_only' AND NOT EXISTS (SELECT 1 FROM loucka_reconstruction.reconstruction_changes c WHERE c.target_time=a.dateTime AND c.variable='outTemp')) SELECT yr,regime,CASE WHEN suspect_zero_hot=1 THEN 'zero_hot_flag' ELSE 'other' END AS sensitivity_group,COUNT(*) AS n,SUM(ABS(ref-y)) AS m0_abs,SUM((ref-y)*(ref-y)) AS m0_sq,SUM(ref-y) AS m0_err,SUM(ABS(model-y)) AS reg_abs,SUM((model-y)*(model-y)) AS reg_sq,SUM(model-y) AS reg_err FROM scored GROUP BY yr,regime,sensitivity_group ORDER BY yr,regime,sensitivity_group;
